import api from '@/shared/api/axiosInstance.ts'
import type { AxiosResponse } from 'axios'
import { useUserStore } from '@/core/stores/user.ts'

export interface Article {
    id: number
    title: string
    link: string
    pub_date: string | Date | null
    summary: string | null
    author: string | null
    image: string | null
    feed_id: number
    fetched_at: string | Date
}

export const ArticleService = {
  async retrieveArticles(): Promise<AxiosResponse<Article[]>> {
    const userStore = useUserStore()
    const username = userStore.user?.username || 'guest'
    return api.get(`/articles/${username}/articles`)
  },

  async retrieveArticlesByFeed(feedId: number): Promise<AxiosResponse<Article[]>> {
    const userStore = useUserStore()
    const username = userStore.user?.username || 'guest'
    return api.get(`/articles/${username}/feed/${feedId}`)
  },

  async retrieveArticle(id: string | number): Promise<AxiosResponse<Article>> {
    return api.get(`/articles/${id}`)
  }
}

import { defineStore } from 'pinia'
import { ref, computed, type Ref } from 'vue'
import { ArticleService, type Article } from '@/shared/api/ArticleService.ts'

export const useArticleStore = defineStore('article', () => {
  const articles = ref<Article[]>([])
  const selectedArticleId = ref<number | null>(null)

  const currentArticle = computed(() => {
    if (!selectedArticleId.value) return null
    return articles.value.find(a => a.id === selectedArticleId.value) || null
  })

  const setArticles = (data: Article[]) => {
    articles.value = data
  }

  const setSelectedId = (id: number) => {
    selectedArticleId.value = id
  }

  async function fetchArticleById(id: number): Promise<Article | null> {
    try {
      const { data } = await ArticleService.retrieveArticle(id)
      if (data) {
        if (!articles.value.find(a => a.id === id)) {
          articles.value.push(data)
        }
        return data
      }
    } catch (e) {
      console.error('Error fetching article:', e)
    }
    return null
  }

  return { 
    articles, 
    selectedArticleId, 
    currentArticle, 
    setArticles, 
    setSelectedId, 
    fetchArticleById 
  }
})

