        INNER JOIN user_feeds uf ON uf.feed_id = a.feed_id
        WHERE uf.user_id = $1 ${searchKey ? 'AND (a.title ILIKE $2 OR a.summary ILIKE $2)' : ''}
        ORDER BY a.pub_date DESC
