import { defineStore } from 'pinia'
import { ref, watch } from 'vue'
import { useUserStore } from './user.ts'
import { useArticleStore } from './article.ts'

export const useSocketStore = defineStore('socket', () => {
  const socket = ref<WebSocket | null>(null)
  const isConnected = ref(false)
  const userStore = useUserStore()
  const articleStore = useArticleStore()

  const connect = () => {
    if (socket.value || !userStore.user?.username) return

    const baseUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000'
    const wsUrl = baseUrl.replace('http', 'ws')

    // The API endpoint for WebSocket usually depends on how Hono is configured.
    // Based on typical Hono/WS setup, it's often the root or a specific /ws endpoint.
    // Let's assume the base URL since the API route didn't show a /ws prefix.
    socket.value = new WebSocket(`${wsUrl}/ws`)

    socket.value.onopen = () => {
      isConnected.value = true
      console.log('[Socket] Connected to API')
    }

    socket.value.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data)
        if (data.type === 'new_articles') {
          console.log(`[Socket] New articles available in feed ${data.feedId}`)
          articleStore.markNewArticlesAvailable()
        }
      } catch (e) {
        console.error('[Socket] Error parsing message', e)
      }
    }

    socket.value.onclose = () => {
      isConnected.value = false
      socket.value = null
      console.log('[Socket] Disconnected. Attempting to reconnect in 5s...')
      setTimeout(connect, 5000)
    }

    socket.value.onerror = (error) => {
      console.error('[Socket] Error:', error)
    }
  }

  const disconnect = () => {
    if (socket.value) {
      socket.value.close()
      socket.value = null
      isConnected.value = false
    }
  }

  // Auto-connect when user logs in
  watch(() => userStore.user, (user) => {
    if (user) {
      connect()
    } else {
      disconnect()
    }
  }, { immediate: true })

  return {
    isConnected,
    connect,
    disconnect
  }
})
