async function bootstrap() {
    try {
        await runMigrations()
        console.log('🚀 DB migrations applied')
        startCron()
    } catch (e) {
        console.error('❌ Failed to bootstrap application:', e)
        process.exit(1)
    }
}

bootstrap()

const app = new Hono()
const { injectWebSocket, upgradeWebSocket } = createNodeWebSocket({ app })

app.use('*', cors())

//app.use('*', ssrfMiddleware)
