import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { UserService, type User } from '@/shared/api/UserService.ts'
import { useRouter } from 'vue-router'

export const useUserStore = defineStore('user', () => {
  const router = useRouter()
  // Initialize state from localStorage to persist across refreshes
  const user = ref<User | null>(
    localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')!) : null
  )
  const accessToken = ref<string | null>(localStorage.getItem('access_token') ?? null)
  const refreshToken = ref<string | null>(localStorage.getItem('refresh_token') ?? null)

  const isAuthenticated = computed(() => !!accessToken.value)

  async function login(username: string, password: string) {
    const { data } = await UserService.login({ username, password })

    user.value = data.user
    accessToken.value = data.accessToken
    refreshToken.value = data.refreshToken

    // Persist to localStorage
    localStorage.setItem('user', JSON.stringify(data.user))
    localStorage.setItem('access_token', data.accessToken)
    localStorage.setItem('refresh_token', data.refreshToken)
    router.push('/home')
  }

  async function register(username: string, password: string) {
    await UserService.register({ username, password })
  }

  async function logout() {
    if (refreshToken.value) {
      try {
        await UserService.logout(refreshToken.value)
        router.push('/login');
      } catch (e) {
        console.error('Logout error:', e)
      }
    }

    user.value = null
    accessToken.value = null
    refreshToken.value = null

    // Clear localStorage
    localStorage.removeItem('user')
    localStorage.removeItem('access_token')
    localStorage.removeItem('refresh_token')
  }

  return { 
    user, 
    accessToken, 
    refreshToken, 
    isAuthenticated, 
    login, 
    register, 
    logout 
  }
})

import api from '@/shared/api/axiosInstance.ts'
import type { AxiosResponse } from 'axios'

export interface User {
    id: number
    username: string
    created_at: string
}

export interface AuthResponse {
    accessToken: string
    refreshToken: string
    user: User
}

export interface LoginRequest {
    username: string
    password: string
}

export interface RegisterRequest {
    username: string
    password: string
}

export interface RefreshRequest {
    refreshToken: string
}

export const UserService = {
  async login(data: LoginRequest): Promise<AxiosResponse<AuthResponse>> {
    return api.post('/auth/login', data)
  },

  async register(data: RegisterRequest): Promise<AxiosResponse<User>> {
    return api.post('/auth/register', data)
  },

  async refresh(data: RefreshRequest): Promise<AxiosResponse<{ accessToken: string }>> {
    return api.post('/auth/refresh', data)
  },

  async logout(refreshToken: string): Promise<AxiosResponse> {
    return api.post('/auth/logout', { refreshToken })
  },

  async getProfile(): Promise<AxiosResponse<User>> {
    return api.get('/users/me')
  },

  async updatePassword(newPassword: string): Promise<AxiosResponse> {
    return api.patch('/users/me/password', { newPassword })
  },

  async deleteAccount(): Promise<AxiosResponse> {
    return api.delete('/users/me')
  }
}

import { defineStore } from 'pinia'
import { ref, computed, type Ref } from 'vue'
import { ArticleService, type Article } from '@/shared/api/ArticleService.ts'

export const useArticleStore = defineStore('article', () => {
  const articles = ref<Article[]>([])
  const selectedArticleId = ref<number | null>(null)
  const hasNewArticles = ref(false)
  const refreshRequested = ref(false)

  const currentArticle = computed(() => {
    if (!selectedArticleId.value) return null
    return articles.value.find(a => a.id === selectedArticleId.value) || null
  })

  const setArticles = (data: Article[]) => {
    articles.value = data
    hasNewArticles.value = false
  }

  const setSelectedId = (id: number) => {
    selectedArticleId.value = id
  }

  const markNewArticlesAvailable = () => {
    hasNewArticles.value = true
  }

  async function fetchArticleById(id: number): Promise<Article | null> {
    try {
      const { data } = await ArticleService.retrieveArticle(id)
      if (data) {
        if (!articles.value.find(a => a.id === id)) {
          articles.value.push(data)
        }
        return data
      }
    } catch (e) {
      console.error('Error fetching article:', e)
    }
    return null
  }

  return { 
    articles, 
    selectedArticleId, 
    currentArticle, 
    setArticles, 
    setSelectedId, 
    fetchArticleById 
  }
})

import { defineStore } from 'pinia'
import { ref, watch } from 'vue'
import { useUserStore } from './user.ts'
import { useArticleStore } from './article.ts'

export const useSocketStore = defineStore('socket', () => {
  const socket = ref<WebSocket | null>(null)
  const isConnected = ref(false)
  const userStore = useUserStore()
  const articleStore = useArticleStore()

  const connect = () => {
    if (socket.value || !userStore.user?.username) return

    const baseUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000'
    const wsUrl = baseUrl.replace('http', 'ws')
    const username = userStore.user.username

    socket.value = new WebSocket(`${wsUrl}/ws/${username}`)

    socket.value.onopen = () => {
      isConnected.value = true
      console.log('[Socket] Connected to API')
    }

    socket.value.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data)
        if (data.type === 'new_articles') {
          console.log(`[Socket] New articles available in feed ${data.feedId}`)
          articleStore.markNewArticlesAvailable()
        }
      } catch (e) {
        console.error('[Socket] Error parsing message', e)
      }
    }

    socket.value.onclose = () => {
      isConnected.value = false
      socket.value = null
      console.log('[Socket] Disconnected. Attempting to reconnect in 5s...')
      setTimeout(connect, 5000)
    }

    socket.value.onerror = (error) => {
      console.error('[Socket] Error:', error)
    }
  }

  const disconnect = () => {
    if (socket.value) {
      socket.value.close()
      socket.value = null
      isConnected.value = false
    }
  }

  // Auto-connect when user logs in
  watch(() => userStore.user, (user) => {
    if (user) {
      connect()
    } else {
      disconnect()
    }
  }, { immediate: true })

  return {
    isConnected,
    connect,
    disconnect
  }
})

