import { Hono } from 'hono'
import {upsertFeed, getFeedById, deleteFeed} from '../repositories/feed.repository.js'
import {
    subscribeUserToFeed,
    unsubscribeUserFromFeed,
    getFeedsByUser
} from '../repositories/user-feed.repository.js'
import { insertArticles } from '../repositories/article.repository.js'
import { getArticles } from '../services/article.service.js'
import {detectSource, type SourceDetectionResult} from '../services/detection.service.js'
import { getUserByUsername, getUserById } from '../repositories/user.repository.js'
import {FeedError, FeedErrors} from '../utils/errors.js'
import {createFeed, nameSchema} from "../validators/feed.validator.js";

const feedRoute = new Hono()

// POST /feeds/:userId
feedRoute.post('/:username', async (c) => {
    const username: string = c.req.param('username');
    const body = await c.req.json()
    const parsed = createFeed.safeParse(body)

    if (!parsed.success) {
        return c.json({ error: parsed.error.issues[0].message }, 400)
    }

    const user = await getUserByUsername(username)
    if (!user) return c.json({ error: 'Utilisateur introuvable' }, 404)

    // 1. Détecter l'URL du feed RSS à partir de l'URL du site
    const detection: SourceDetectionResult = await detectSource(parsed.data.url)
    if (!detection.feedUrl)
        return c.json({ error: 'Aucun flux RSS détecté sur ce site', code: 'NO_FEED' }, 422)


    try {
        const feedData = await getArticles(detection.feedUrl)

        const feed = await upsertFeed({
            type: detection.type === 'atom' ? 'atom' : 'rss',
            feed_url: detection.feedUrl,
            original_url: parsed.data.url,
            name: feedData.title,
        })

        const subscription = await subscribeUserToFeed(user.id, feed.id)

        const inserted = await insertArticles(feedData.articles.map((a) => ({
            feed_id: feed.id,
            title: a.title,
            link: a.link,
            pub_date: a.date,
            summary: a.summary,
            author: a.author,
            image: a.image,
        })))

        return c.json({ feed, subscription, articlesInserted: inserted }, 201)
    } catch (e) {
        if (e instanceof FeedError) {
            const status = e.code === 'NOT_FOUND' ? 404 : 422
            return c.json({ error: e.message, code: e.code }, status)
        }
        return c.json({ error: 'Erreur inattendue' }, 500)
    }
})

// DELETE /feeds/:feedId/users/:username ✅
feedRoute.delete('/:feedId/users/:username', async (c) => {
    const feedId: number = Number(c.req.param('feedId'))
    const username: string = String(c.req.param('username'))

    const user = await getUserByUsername(username)

    if (!user) return c.json({ error: FeedErrors.USER_NOT_FOUND.message }, 404)

    const feed = await getFeedById(feedId)
    if (!feed) return c.json({ error: FeedErrors.FEED_NOT_FOUND.message }, 404)

    await unsubscribeUserFromFeed(user.id, feedId)
    return c.json({ message: FeedErrors.UNSUBSCRIBE_SUCCESS.message })
})

// GET /feeds/by-username/:username — récupérer les feeds via le username ✅
feedRoute.get('/by-username/:username', async (c) => {
    const username = c.req.param('username')
    const user = await getUserByUsername(username)

    if (!user) return c.json({ error: 'Utilisateur introuvable' }, 404)

    const feeds = await getFeedsByUser(user.id)
    return c.json(feeds)
})

export default feedRouteimport { Hono } from 'hono'
import {getArticles} from "../services/article.service.js";
import {urlArraySchema, urlSchema} from "../validators/feed.validator.js";
import {FeedError} from "../utils/errors.js";
import {getUserByUsername} from "../repositories/user.repository.js";
import {getArticlesByUser, getArticlesByUserAndFeed, getArticleById, countArticlesByUser, countArticlesByUserAndFeed} from "../repositories/article.repository.js";
import articleRoute from "./article.route.js";

const articlesRoute = new Hono()

articlesRoute.post('/', async (c) => {
    const body = await c.req.json()
    const parsed = urlArraySchema.safeParse(body)

    if (!parsed.success)
        return c.json({ error: parsed.error.issues[0].message }, 400)

    const results = await Promise.allSettled(parsed.data.map(getArticles))

    const success = []
    const failed = []

    for (let i = 0; i < results.length; i++) {
        const result = results[i]
        if (result.status === 'fulfilled') {
            success.push(result.value)
        } else {
            const err = result.reason
            failed.push({
                feedUrl: parsed.data[i],
                error: err instanceof FeedError ? err.message : 'Erreur inattendue',
                code:  err instanceof FeedError ? err.code   : 'UNKNOWN',
            })
        }
    }

    return c.json({
        total: success.length,
        failed: failed.length > 0 ? failed : undefined,
        feeds: success,
    })
})

// GET /articles/:username/articles
articlesRoute.get('/:username/articles', async (c) => {
    const username: string = String(c.req.param('username'))
    const size = Number(c.req.query('size') ?? 100)
    const index = Number(c.req.query('index') ?? 0)
    const searchKey = c.req.query('searchKey') || null

    const user = await getUserByUsername(username)
    if (!user) return c.json({ error: 'Utilisateur introuvable' }, 404)

    const offset = index * size
    const articles = await getArticlesByUser(user.id, size, offset, searchKey)
    const total = await countArticlesByUser(user.id, searchKey)

    return c.json({
        total,
        size,
        index,
        objects: articles
    })
})

// GET /articles/:username/feed/:feedId
articlesRoute.get('/:username/feed/:feedId', async (c) => {
    const username: string = String(c.req.param('username'))
    const feedId: number = Number(c.req.param('feedId'))
    const size = Number(c.req.query('size') ?? 100)
    const index = Number(c.req.query('index') ?? 0)
    const searchKey = c.req.query('searchKey') || null

    const user = await getUserByUsername(username)
    if (!user) return c.json({ error: 'Utilisateur introuvable' }, 404)

    const offset = index * size
    const articles = await getArticlesByUserAndFeed(user.id, feedId, size, offset, searchKey)
    const total = await countArticlesByUserAndFeed(user.id, feedId, searchKey)

    return c.json({
        total,
        size,
        index,
        objects: articles
    })
})

// GET /articles/:id
articlesRoute.get('/:id', async (c) => {
    const id = Number(c.req.param('id'))
    if (isNaN(id)) return c.json({ error: 'ID invalide' }, 400)

    const article = await getArticleById(id)
    if (!article) return c.json({ error: 'Article introuvable' }, 404)
    return c.json(article)
})

export default articlesRoute
import { Hono } from 'hono'
import { z } from 'zod'
import { createUser, getUserById, getUserByUsername, usernameExists, updatePassword } from '../repositories/user.repository.js'
import { getArticlesByUser } from '../repositories/article.repository.js'
import {createUserSchema} from "../validators/feed.validator.js";

const userRoute = new Hono()

// GET /users/me — récupérer son propre profil ✅
userRoute.get('/me', async (c) => {
    const userId = c.get('userId')
    if (!userId) return c.json({ error: 'Utilisateur non authentifié' }, 401)

    const user = await getUserById(userId)
    if (!user) return c.json({ error: 'Utilisateur introuvable' }, 404)

    const { password, ...userWithoutPassword } = user
    return c.json(userWithoutPassword)
})

// PATCH /users/me/password — changer son mot de passe
userRoute.patch('/me/password', async (c) => {
    const userId = c.get('userId')
    const { newPassword } = await c.req.json()

    if (!newPassword || newPassword.length < 6) {
        return c.json({ error: 'Le mot de passe doit contenir au moins 6 caractères' }, 400)
    }

    try {
        await updatePassword(userId, newPassword)
        return c.json({ message: 'Mot de passe mis à jour avec succès' })
    } catch (e) {
        return c.json({ error: 'Erreur lors de la mise à jour du mot de passe' }, 500)
    }
})

// DELETE /users/me — supprimer son propre compte
userRoute.delete('/me', async (c) => {
    const userId = c.get('userId')
    if (!userId) return c.json({ error: 'Utilisateur non authentifié' }, 401)

    try {
        await deleteUser(userId)
        return c.json({ message: 'Compte supprimé avec succès' })
    } catch (e) {
        return c.json({ error: 'Erreur lors de la suppression du compte' }, 500)
    }
})

// GET /users/check-username?username=xxx ✅
userRoute.get('/check-username', async (c) => {
    const username = c.req.query('username')

    if (!username || username.trim() === '')
        return c.json({ error: 'Le paramètre username est requis' }, 400)


    const taken = await usernameExists(username.trim())
    return c.json({ username: username.trim(), available: !taken })
})

// GET /users/:id/articles — lister les articles d'un user
userRoute.get('/:id/articles', async (c) => {
    const userId = Number(c.req.param('id'))
    const limit = Number(c.req.query('limit') ?? 100)

    const user = await getUserById(userId)
    if (!user) return c.json({ error: 'Utilisateur introuvable' }, 404)

    const articles = await getArticlesByUser(userId, limit)
    return c.json(articles)
})

export default userRoute

import { createMiddleware } from 'hono/factory'
import {verifyToken} from "../services/auth.service.js";

export const authMiddleware = createMiddleware(async (c, next) => {
    const authHeader = c.req.header('Authorization')
    const authAppHeader = c.req.header('X-App-Token')

    if (!authAppHeader || !authAppHeader.startsWith('cs ')) {
        return c.json({ error: 'Access denied' }, 403)
    }

    const apiToken = authAppHeader?.split(' ')[1];
    if (apiToken !== process.env.API_SECRET_TOKEN) {
        return c.json({ error: 'Access denied' }, 401)
    }

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return c.json({ error: 'Invalid token' }, 403)
    }

    const token = authHeader.split(' ')[1]

    try {
        const payload = await verifyToken(token)

        if (payload.type !== 'access') {
            return c.json({ error: 'Token invalide' }, 401)
        }

        c.set('userId', payload.userId)
        c.set('username', payload.username)
        await next()
    } catch {
        return c.json({ error: 'Token invalide ou expiré' }, 401)
    }
